[{"order":1,"type":"heading","text":"Writing Centralized Error-Handling Middleware in Express.js"},{"order":2,"type":"paragraph","text":"Error handling is a critical aspect of building robust web applications. In Express.js, centralizing your error handling allows you to manage application errors from a single location. This approach guarantees consistent error responses, simplifies logging, and keeps route handlers clean and readable."},{"order":3,"type":"subheading","text":"Understanding Express Error Middleware"},{"order":4,"type":"paragraph","text":"Express identifies a middleware function as an error handler by checking if it accepts exactly four parameters: (err, req, res, next). Skipping any of these parameters, even 'next', causes Express to process it as standard request middleware instead."},{"order":5,"type":"subheading","text":"Step 1: Creating a Custom Operational Error Class"},{"order":6,"type":"paragraph","text":"Custom error classes allow you to attach HTTP status codes and operational flags to error objects. Operational errors represent predictable runtime issues like invalid user input or missing resources."},{"order":7,"type":"code","text":"class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = String(statusCode).startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;"},{"order":8,"type":"subheading","text":"Step 2: Defining the Centralized Error Middleware"},{"order":9,"type":"paragraph","text":"Create a centralized middleware function to format responses cleanly. In production environments, sensitive information like call stack traces should be hidden."},{"order":10,"type":"code","text":"const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  const isDev = process.env.NODE_ENV === 'development';

  res.status(err.statusCode).json({
    status: err.status,
    message: err.message || 'Internal Server Error',
    ...(isDev && { stack: err.stack })
  });
};

module.exports = errorHandler;"},{"order":11,"type":"subheading","text":"Step 3: Handling Asynchronous Errors Safely"},{"order":12,"type":"paragraph","text":"Express catches synchronous errors automatically when thrown inside route handlers. However, for async functions, rejected promises must be forwarded to next() or wrapped inside an execution utility."},{"order":13,"type":"code","text":"const catchAsync = (fn) => {
  return (req, res, next) => {
    fn(req, res, next).catch(next);
  };
};

module.exports = catchAsync;"},{"order":14,"type":"subheading","text":"Step 4: Wire Everything Into the Express Application"},{"order":15,"type":"paragraph","text":"To activate the error handler, register it at the very bottom of your application stack, after all other routes and middleware definitions."},{"order":16,"type":"code","text":"const express = require('express');
const AppError = require('./AppError');
const catchAsync = require('./catchAsync');
const errorHandler = require('./errorHandler');

const app = express();
app.use(express.json());

app.get('/api/users/:id', catchAsync(async (req, res, next) => {
  const user = null; // Simulating database query result

  if (!user) {
    return next(new AppError('No user found with that ID', 404));
  }

  res.status(200).json({ status: 'success', data: user });
}));

// Register global error middleware last
app.use(errorHandler);

app.listen(3000, () => console.log('Server started on port 3000'));"},{"order":17,"type":"subheading","text":"Key Best Practices"},{"order":18,"type":"bullet_point","text":"Always register the error middleware function as the final app.use() declaration."},{"order":19,"type":"bullet_point","text":"Ensure error handler middleware functions strictly maintain the four-parameter signature: (err, req, res, next)."},{"order":20,"type":"bullet_point","text":"Differentiate between operational errors (4xx client issues) and unexpected system bugs (5xx server bugs) in production logging."}]
